import { useEffect, useMemo, useState } from 'react';

import { getUrlParams } from '@common/utils/router';

/**
 * Reads URL hash parameters and re-parses them whenever the hash changes.
 * Useful for preloaded popup windows that receive new data via hash updates.
 */
export const useUrlHashParams = () => {
    const [urlHash, setUrlHash] = useState(typeof window !== 'undefined' ? window.location.hash : '');

    useEffect(() => {
        const onHashChange = () => setUrlHash(window.location.hash);

        window.addEventListener('hashchange', onHashChange);
        return () => window.removeEventListener('hashchange', onHashChange);
    }, []);

    return useMemo(() => getUrlParams(urlHash), [urlHash]);
};
